"""Props generated by asset_agent (Anthropic API) and saved as JSON in data/venue_refs/generated_props/. Add 'proc_generated' to realize.PROP_MODULES and any
catalog `proc:<Name>Factory` src resolves here: module __getattr__ builds the factory from <Name>.json on first use."""
from __future__ import annotations

import json
import os
from pathlib import Path

DIR = Path(os.environ.get("ROOM_GENERATED_PROPS", "/jarvis/project/robomituba/data/venue_refs/generated_props"))


def names():
    return sorted(p.stem + "Factory" for p in DIR.glob("*.json"))


def __getattr__(attr):
    if attr.endswith("Factory") and (DIR / f"{attr[:-7]}.json").is_file():
        from room_planner.prop_dsl import build_factory
        return build_factory(json.loads((DIR / f"{attr[:-7]}.json").read_text()))
    raise AttributeError(attr)
